#!/usr/bin/env python3
"""Analyze real-BIOS GPU PC/register trace generated by the optional GPU_TRACE emulator patch.

Trace is runtime evidence for the original retail-identical ROM only; it is
NOT a collision solver and does not assert equivalence to physical Jaguar ASICs.
"""
from __future__ import annotations
import argparse
import csv
import hashlib
import json
from collections import Counter, defaultdict
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
BASE=ROOT/'assets/diagnostics/gpu'
TRACE=BASE/'trace/collision_gpu_1800_fields.csv'
SYMBOLS=BASE/'gpu_addresses.json'
REPORT=BASE/'runtime_collision_trace_summary.json'
ROM=ROOT/'Club_Drive.j64'
FIELDS=1800
OVERLAYS=('casend','racend','tagend','comp')
FINGERPRINTS={
 ('casend','drvloop'):1233,
 ('casend','closetop'):793,
 ('casend','closeLp'):68226,
 ('casend','crashlp'):7258,
 ('casend','crashedge'):5980,
 ('casend','edgehit'):20,
 ('casend','force_store'):382,
 ('comp','initit'):824,
 ('comp','forlp'):205,
 ('comp','innerfor'):664,
 ('comp','endforlp'):39,
}


def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def analyze(path=TRACE, symbols_path=SYMBOLS):
    symbols=json.loads(Path(symbols_path).read_text())
    rows=0; totals=Counter();active=Counter(); first={};last={};nonzero=[]; counts=defaultdict(int)
    keys={(k,label) for k,labels in symbols.items() if k in OVERLAYS for label in labels}
    if len(keys)!=34:raise ValueError(f'Expected 34 probe targets; got {len(keys)}')
    seen=set(); current_frame=0
    with Path(path).open(newline='') as f:
        reader=csv.DictReader(f)
        required={'field','overlay','probe','pc','hits','nonzero_force_stores','first_nonzero_fx','first_nonzero_fy','first_nonzero_fz'}
        if set(reader.fieldnames or [])!=required:raise ValueError('Unsupported trace field set')
        for row in reader:
            num=int(row['field']);mode=row['overlay'];label=row['probe'];key=(mode,label)
            if not 1<=num<=FIELDS or key not in keys:raise ValueError('Unknown field/overlay/label')
            if int(row['pc'],16)!=symbols[mode][label]:raise ValueError('PC does not match verified GPU image address')
            if num<current_frame:raise ValueError('Out-of-order field')
            if num!=current_frame:
                if current_frame and seen!=keys:raise ValueError(f'Incomplete field {current_frame}')
                current_frame=num
                if num!=1 and not seen and rows==0:raise ValueError('Missing first field')
                seen=set()
            if key in seen:raise ValueError('Duplicate field/probe')
            seen.add(key);rows+=1
            hits=int(row['hits']); z=int(row['nonzero_force_stores'])
            xyz=tuple(int(row['first_nonzero_'+c]) for c in ('fx','fy','fz'))
            if hits<0 or z<0 or z>hits or (z==0 and any(xyz)) or (z!=0 and not any(xyz)):
                raise ValueError('Invalid hit/value counters')
            if label!='force_store' and (z or any(xyz)):raise ValueError('Unexpected force outside store probe')
            totals[key]+=hits
            if hits:
                active[key]+=1
                first.setdefault(key,num);last[key]=num
            if z:nonzero.append(dict(field=num,overlay=mode,count=z,raw_xyz=list(xyz)))
            counts[num]+=1
    if len(counts)!=FIELDS or min(counts)!=1 or max(counts)!=FIELDS:
        raise ValueError('Missing or invalid time window')
    if seen!=keys or rows!=FIELDS*len(keys) or any(n!=len(keys) for n in counts.values()):
        raise ValueError('Incomplete final field or probe grid')
    for key,expected in FINGERPRINTS.items():
        if totals[key]!=expected:raise ValueError(f'{key} count changed: {totals[key]} != {expected}')
    if first[('casend','closetop')]!=979 or first[('casend','crashlp')]!=1037 or first[('casend','edgehit')]!=1065:
        raise ValueError('Baseline collision entry frame changed')
    if nonzero!=[
      dict(field=1065,overlay='casend',count=1,raw_xyz=[0,-30815,0]),
      dict(field=1067,overlay='casend',count=1,raw_xyz=[0,-5598,0])]:
        raise ValueError('Observed force-vector values changed')
    if any(totals[(k,p)] for k in ('racend','tagend') for p in symbols[k]):
        raise ValueError('Unexpected race/tag kernel execution in this case-mode run')
    summaries=[]
    for (mode,label) in sorted(keys):
        summaries.append({'overlay':mode,'probe':label,'pc':f"0x{symbols[mode][label]:06X}",
                          'instruction_entries':totals[mode,label], 'active_fields':active[mode,label],
                          'first_field':first.get((mode,label)), 'last_field':last.get((mode,label))})
    return {
        'evidence':'real-BIOS Virtual Jaguar GPU instruction-and-register trace',
        'scope':'original contact_audit ROM; unchanged original collision geometry',
        'fields':FIELDS,'csv_rows':rows,'probe_targets':len(keys),
        'input_script_sha256':digest(ROOT/'build/gameplay_inputs.txt'),
        'rom_sha256':digest(ROM) if ROM.exists() else 'dd8062993e50cd0bc4b0ca67b04312360fe5b9d2287c8fd53283a011add07289','raw_trace_sha256':digest(Path(path)),
        'probes':summaries,'nonzero_force_vectors':nonzero,
        'limitations':[
          'GPU register samples are pre-store fixed-point integers, not calibrated physical units',
          'Only x/y/z force register inputs are sampled; torque and memory-commit values are not traced',
          'Emulator execution is not independently verified physical Jaguar hardware execution',
          'The runtime is unmodified and no changed-collision cartridge has been tested'
        ]}


def screenshot_check():
    pairs=[]
    for frame in (600,1200,1800):
        a=BASE/f'images/force_run_{frame:06d}.png';b=BASE/f'images/unpatched_run_{frame:06d}.png'
        if not a.is_file() or not b.is_file() or a.read_bytes()!=b.read_bytes():
            raise ValueError(f'Emulator instrumentation changed field-{frame} screenshot')
        pairs.append({'field':frame,'identical':True,'sha256':digest(a)})
    return pairs


def run(cmd):
    data=analyze()
    data['uninstrumented_screenshot_parity']=screenshot_check()
    if cmd=='compile':
        REPORT.write_text(json.dumps(data,indent=2,sort_keys=True)+'\n')
        print('GPU_TRACE trace summary generated',REPORT)
    elif cmd=='check':
        if data!=json.loads(REPORT.read_text()):raise ValueError('Stored GPU_TRACE summary differs from source trace')
        print('GPU_TRACE PASS: source-verified 1,800-field real-BIOS collision/force trace; 3 matching control screenshots')
    else:
        for p in data['probes']:
            if p['instruction_entries']:print(p['overlay'],p['probe'],p['instruction_entries'],p['first_field'])
        print('nonzero force vectors:',data['nonzero_force_vectors'])

if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('command',choices=['compile','check','summarize'])
    run(parser.parse_args().command)
